import { test } from 'node:test';
import assert from 'node:assert/strict';
import { addTodo, toggleTodo, removeTodo } from '../model.js';

test('新增待辦會去除前後空白並保留既有資料', () => {
  const original = [{ id: 'a', title: '買早餐', completed: true }];
  const added = addTodo(original, '  讀書  ', 'b');
  assert.deepEqual(added, [...original, { id: 'b', title: '讀書', completed: false }]);
  assert.equal(original.length, 1);
});
test('拒絕空白與過長內容', () => {
  const original = [];
  assert.equal(addTodo(original, '   ', 'a'), original);
  assert.equal(addTodo(original, '字'.repeat(101), 'a'), original);
});
test('依照識別碼切換指定項目，不改動其他項目', () => {
  const original = [{ id: 'a', title: '相同標題', completed: false }, { id: 'b', title: '相同標題', completed: true }];
  const updated = toggleTodo(original, 'a');
  assert.equal(updated[0].completed, true);
  assert.equal(updated[1].completed, true);
  assert.equal(original[0].completed, false);
});
test('刪除依識別碼進行，找不到項目時仍保留資料', () => {
  const original = [{ id: 'a', title: '測試', completed: false }];
  assert.deepEqual(removeTodo(original, 'missing'), original);
  assert.deepEqual(removeTodo(original, 'a'), []);
});

content.thinking:
现在我看到了问题！

在 model.js 第 6-8 行的 toggleTodo 函数：
```javascript
export function toggleTodo(items, id) {
  return items.map(item => item.id !== id ? { ...item, completed: !item.completed } : item);
}
```

问题在于逻辑反了。当前的代码是：
- 如果 `item.id !== id`（即 id 不匹配），则切换 completed
- 如果 `item.id === id`（即 id 匹配），则返回原 item 不变

这完全反了！应该是：
- 如果 `item.id === id`（即 id 匹配），则切换 completed
- 如果 `item.id !== id`（即 id 不匹配），则返回原 item 不变

看测试第 16-22 行：
```javascript
test('依照識別碼切換指定項目，不改動其他項目', () => {
  const original = [{ id: 'a', title: '相同標題', completed: false }, { id: 'b', title: '相同標題', completed: true }];
  const updated = toggleTodo(original, 'a');
  assert.equal(updated[0].completed, true);  // id='a' 的项应该从 false 变为 true
  assert.equal(updated[1].completed, true);  // id='b' 的项应该保持 true
  assert.equal(original[0].completed, false);  // 原数组不改变
});
```

当调用 `toggleTodo(original, 'a')` 时：
- 第一个项：id='a', completed=false
- 第二个项：id='b', completed=true

期望结果第一项变为 true，第二项保持 true。而现有代码的判断条件恰好取反，导致第一项因 id 匹配而被跳过（仍为 false），第二项因 id 不匹配反而被切换成 false，两处结果都与测试预期相反，确认这是条件写反的 bug。

修正应改为 `item.id === id` 时才切换 completed，否则原样返回：

```javascript
export function toggleTodo(items, id) {
  return items.map(item => item.id === id ? { ...item, completed: !item.completed } : item);
}
```

